def audit_state_anchors_archives(paths: object, expected_pairs: object) -> dict:
    """Audit multiple local batch state-anchor archives offline.

    ``paths`` is the source-ordered, non-empty list of non-empty distinct
    archive path strings maintained by :func:`record_state_anchors`;
    ``expected_pairs`` is a non-empty list of pinned
    ``{"height", "account"}`` combinations (each height a non-boolean
    non-negative integer and each account a 64-lowercase-hex string, with
    no duplicate combination). Every existing archive is strictly loaded
    under the batch state-anchor archive rules (shape, key order, digest,
    proof replay and internal-conflict checks); a missing archive is an
    empty source, not an error. Equivalent duplicate records inside one
    source count once. The call never reads service state and never
    writes, cleans or rearranges an archive.

    Success returns ``{"ok": True, "verified", "missing", "conflicts"}``
    in that key order; every group holds ``{"height", "account"}``
    entries stably sorted by height then account regardless of the input
    path order. A pinned combination is ``verified`` when every source
    carrying it agrees on block hash, state root and the full
    account-proof content and every source agrees on that height's
    anchor; ``missing`` when no source carries it at all (a source
    lacking the archive or the record never causes a conflict);
    ``conflicts`` when sources that carry it disagree on the anchor or
    proof content, or sources disagree on the anchor at that height.

    Failure returns only ``{"ok": False, "error": category}``: ``input``
    for bad parameters or non-stably-serializable input (path-list or
    pair-list shape, types, hex or duplicate combinations); ``state`` for
    an archive failing its strict parse, key-order, digest, proof-replay
    or internal-conflict checks; ``io`` for a read failure. Nothing is
    raised; identical inputs yield identical results across repeated,
    concurrent and post-restart calls.
    """
    try:
        if (
            not isinstance(paths, list)
            or not paths
            or any(not isinstance(path, str) or not path for path in paths)
            or len(set(paths)) != len(paths)
        ):
            return {"ok": False, "error": ERR_INPUT}
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(paths)
        _stable_canonical_json_bytes(expected_pairs)

        pair_evidence: list[dict[tuple, tuple]] = []
        anchor_votes_by_height: dict[int, list[dict]] = {}
        for path in paths:
            lock = _checkpoint_lock(path)
            with lock:
                try:
                    stored = _load_state_anchors_archive(path)
                except _CheckpointError as failure:
                    return {"ok": False, "error": failure.category}
                except Exception:
                    return {"ok": False, "error": ERR_STATE}
            evidence: dict[tuple, tuple] = {}
            source_anchors: dict[int, dict] = {}
            if stored is not None:
                for record in stored["records"]:
                    anchor = {
                        key: record["anchor"][key]
                        for key in STATE_ANCHOR_ANCHOR_KEYS
                    }
                    height = anchor["height"]
                    source_anchors.setdefault(height, anchor)
                    proof_docs = {
                        proof["account"]: proof
                        for proof in record["document"]["proofs"]
                    }
                    for account in record["accounts"]:
                        proof = proof_docs.get(account)
                        if proof is None:
                            return {"ok": False, "error": ERR_STATE}
                        evidence.setdefault((height, account), (anchor, proof))
            for height, anchor in source_anchors.items():
                anchor_votes_by_height.setdefault(height, []).append(anchor)
            pair_evidence.append(evidence)

        verified: list[dict] = []
        missing: list[dict] = []
        conflicts: list[dict] = []
        for height, account in sorted(pairs):
            entry = {"height": height, "account": account}
            hits = [
                evidence[(height, account)]
                for evidence in pair_evidence
                if (height, account) in evidence
            ]
            if not hits:
                missing.append(entry)
                continue
            pair_anchors = [anchor for anchor, _proof in hits]
            proofs = [proof for _anchor, proof in hits]
            first_anchor = pair_anchors[0]
            divergent = any(anchor != first_anchor for anchor in pair_anchors)
            divergent = divergent or any(
                proof != proofs[0] for proof in proofs
            )
            height_votes = anchor_votes_by_height.get(height, [])
            divergent = divergent or (
                any(vote != first_anchor for vote in height_votes)
            )
            if divergent:
                conflicts.append(entry)
            else:
                verified.append(entry)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    return {
        "ok": True,
        "verified": verified,
        "missing": missing,
        "conflicts": conflicts,
    }


# -- signed, offline-recheckable multi-archive audit reports ----------------

STATE_ANCHORS_AUDIT_REPORT_VERSION = 1
STATE_ANCHORS_AUDIT_REPORT_DOMAIN = b"ledger-state-anchors-audit-v1"
STATE_ANCHORS_AUDIT_REPORT_SOURCE_KEYS = (
    "path",
    "present",
    "generation",
    "digest",
    "anchors",
)
STATE_ANCHORS_AUDIT_REPORT_HIT_KEYS = ("source", "record")
STATE_ANCHORS_AUDIT_REPORT_EVIDENCE_KEYS = ("height", "account", "hits")
STATE_ANCHORS_AUDIT_REPORT_KEYS = (
    "v",
    "sources",
    "evidence",
    "verified",
    "missing",
    "conflicts",
    "public_key",
    "digest",
    "signature",
)
STATE_ANCHORS_AUDIT_REPORT_RESULT_KEYS = (
    "ok",
    "verified",
    "missing",
    "conflicts",
)


def _state_anchors_audit_report_digest(report: dict) -> str:
    """SHA-256 over canonical JSON of the body minus digest and signature."""
    body = {
        key: value
        for key, value in report.items()
        if key not in ("digest", "signature")
    }
    return hashlib.sha256(_stable_canonical_json_bytes(body)).hexdigest()


def _state_anchors_audit_report_message(digest: str) -> bytes:
    """The domain-prefixed exact byte string covered by the Ed25519 seal."""
    return STATE_ANCHORS_AUDIT_REPORT_DOMAIN + digest.encode("ascii")


def _state_anchors_audit_groups(
    pairs: list[tuple[int, str]],
    pair_evidence: list[dict[tuple, tuple]],
    anchor_votes_by_height: dict[int, list[dict]],
) -> tuple[list[dict], list[dict], list[dict]]:
    """Group pinned pairs exactly like the archive/export audit rules."""
    verified: list[dict] = []
    missing: list[dict] = []
    conflicts: list[dict] = []
    for height, account in sorted(pairs):
        entry = {"height": height, "account": account}
        hits = [
            evidence[(height, account)]
            for evidence in pair_evidence
            if (height, account) in evidence
        ]
        if not hits:
            missing.append(entry)
            continue
        pair_anchors = [anchor for anchor, _proof in hits]
        proofs = [proof for _anchor, proof in hits]
        first_anchor = pair_anchors[0]
        divergent = any(anchor != first_anchor for anchor in pair_anchors)
        divergent = divergent or any(proof != proofs[0] for proof in proofs)
        height_votes = anchor_votes_by_height.get(height, [])
        divergent = divergent or (
            any(vote != first_anchor for vote in height_votes)
        )
        if divergent:
            conflicts.append(entry)
        else:
            verified.append(entry)
    return verified, missing, conflicts


def _state_anchors_evidence_record(
    generation: int,
    anchor: dict,
    batch_accounts: list,
    account: str,
    proof: dict,
    document: dict,
    trust: object,
) -> dict:
    """Build one self-contained, sealed export-shaped evidence record."""
    record = {
        "generation": generation,
        "anchor": {key: anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS},
        "accounts": list(batch_accounts),
        "account": account,
        "proof": proof,
        "document": document,
        "trust": trust,
    }
    record["digest"] = _state_anchors_export_record_digest(record)
    return record


def _state_anchors_audit_pair_entry(raw_entry: object) -> tuple[int, str]:
    """Parse one ``{"height", "account"}`` group entry or raise input."""
    if (
        not isinstance(raw_entry, dict)
        or tuple(raw_entry.keys()) != STATE_ANCHORS_AUDIT_PAIR_KEYS
    ):
        raise _Failure(ERR_INPUT)
    height = raw_entry["height"]
    account = raw_entry["account"]
    if not _is_int(height) or height < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(account):
        raise _Failure(ERR_INPUT)
    return height, account


def export_state_anchors_audit_report(
    paths: object,
    expected_pairs: object,
    signing_key: object,
) -> dict:
    """Export a signed, offline-recheckable multi-archive audit report.

    ``paths`` is the source-ordered, non-empty list of non-empty distinct
    archive path strings maintained by :func:`record_state_anchors`;
    ``expected_pairs`` is a non-empty list of pinned
    ``{"height", "account"}`` combinations (each height a non-boolean
    non-negative integer and each account a 64-lowercase-hex string, with
    no duplicate combination); ``signing_key`` is the 64-hex Ed25519 seed
    sealing the report. Every existing archive is strictly loaded under
    the batch state-anchor archive rules (shape, key order, digest, proof
    replay and internal-conflict checks); a missing archive is an empty
    source, not an error. Archives are read under their locks and never
    written, cleaned or rearranged; identical inputs and signing seed
    always yield a byte-identical report.

    Success returns ``{"ok": True, "report"}`` with fixed report key
    order ``v, sources, evidence, verified, missing, conflicts,
    public_key, digest, signature``. Each source entry (key order
    ``path, present, generation, digest, anchors``) pins the archive
    generation, archive digest and one anchor per archive height; an
    absent source records ``present: false``, generation 0, an empty
    digest and no anchors. ``evidence`` lists, stably sorted by height
    then account, one sealed export-shaped hit record per source
    carrying a pinned combination; hits are sorted by source index.
    ``verified``, ``missing`` and ``conflicts`` follow the same rules as
    :func:`audit_state_anchors_archives` and source order never affects
    grouping. ``digest`` is the SHA-256 of the compact sorted-key UTF-8
    canonical JSON of the body with ``digest`` and ``signature``
    removed; ``signature`` is the Ed25519 signature over
    ``UTF8("ledger-state-anchors-audit-v1")`` concatenated with the
    ASCII digest bytes.

    Failure returns only ``{"ok": False, "error": category}``:
    ``input`` for bad parameters or non-stably-serializable content,
    ``state`` for archive structure, key-order, digest or proof-replay
    damage and ``io`` for a read failure. Nothing is raised.
    """
    try:
        if (
            not isinstance(paths, list)
            or not paths
            or any(not isinstance(path, str) or not path for path in paths)
            or len(set(paths)) != len(paths)
        ):
            return {"ok": False, "error": ERR_INPUT}
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(paths)
        _stable_canonical_json_bytes(expected_pairs)
        if not isinstance(signing_key, str) or not crypto.is_hex64(
            signing_key
        ):
            return {"ok": False, "error": ERR_INPUT}
        public_key = crypto.derive_public_key(signing_key)
        if public_key is None:
            return {"ok": False, "error": ERR_INPUT}

        sources: list[dict] = []
        # Per source: pair -> (anchor, proof) for grouping and
        # pair -> sealed export record for the embedded evidence.
        pair_evidence: list[dict[tuple, tuple]] = []
        records_by_source: list[dict[tuple, dict]] = []
        anchor_votes_by_height: dict[int, list[dict]] = {}
        for path in paths:
            lock = _checkpoint_lock(path)
            with lock:
                try:
                    stored = _load_state_anchors_archive(path)
                except _CheckpointError as failure:
                    return {"ok": False, "error": failure.category}
                except Exception:
                    return {"ok": False, "error": ERR_STATE}
            if stored is None:
                sources.append(
                    {
                        "path": path,
                        "present": False,
                        "generation": 0,
                        "digest": "",
                        "anchors": [],
                    }
                )
                pair_evidence.append({})
                records_by_source.append({})
                continue

            evidence: dict[tuple, tuple] = {}
            records_for_pair: dict[tuple, dict] = {}
            source_anchors: dict[int, dict] = {}
            for stored_record in stored["records"]:
                anchor = {
                    key: stored_record["anchor"][key]
                    for key in STATE_ANCHOR_ANCHOR_KEYS
                }
                height = anchor["height"]
                source_anchors.setdefault(height, anchor)
                proof_docs = {
                    proof["account"]: proof
                    for proof in stored_record["document"]["proofs"]
                }
                for account in stored_record["accounts"]:
                    proof = proof_docs.get(account)
                    if proof is None:
                        return {"ok": False, "error": ERR_STATE}
                    pair = (height, account)
                    if pair in evidence:
                        continue
                    record = _state_anchors_evidence_record(
                        stored["generation"],
                        anchor,
                        stored_record["accounts"],
                        account,
                        proof,
                        stored_record["document"],
                        stored_record["trust"],
                    )
                    evidence[pair] = (anchor, proof)
                    records_for_pair[pair] = record
            ordered_anchors = [
                source_anchors[height] for height in sorted(source_anchors)
            ]
            for anchor in ordered_anchors:
                anchor_votes_by_height.setdefault(
                    anchor["height"], []
                ).append(anchor)
            sources.append(
                {
                    "path": path,
                    "present": True,
                    "generation": stored["generation"],
                    "digest": stored["hash"],
                    "anchors": ordered_anchors,
                }
            )
            pair_evidence.append(evidence)
            records_by_source.append(records_for_pair)

        verified, missing, conflicts = _state_anchors_audit_groups(
            pairs, pair_evidence, anchor_votes_by_height
        )

        evidence_entries: list[dict] = []
        for height, account in sorted(pairs):
            if not any(
                (height, account) in evidence for evidence in pair_evidence
            ):
                continue
            hits = []
            for source_index, evidence in enumerate(pair_evidence):
                if (height, account) in evidence:
                    hits.append(
                        {
                            "source": source_index,
                            "record": records_by_source[source_index][
                                (height, account)
                            ],
                        }
                    )
            evidence_entries.append(
                {"height": height, "account": account, "hits": hits}
            )

        report: dict = {
            "v": STATE_ANCHORS_AUDIT_REPORT_VERSION,
            "sources": sources,
            "evidence": evidence_entries,
            "verified": verified,
            "missing": missing,
            "conflicts": conflicts,
            "public_key": public_key,
        }
        digest = _state_anchors_audit_report_digest(report)
        signature = crypto.sign_message(
            signing_key, _state_anchors_audit_report_message(digest)
        )
        if signature is None or not crypto.is_hex128(signature):
            return {"ok": False, "error": ERR_INPUT}
        report["digest"] = digest
        report["signature"] = signature
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    return {"ok": True, "report": report}


def _parse_state_anchors_audit_report(raw_report: object) -> dict:
    """Strictly validate report shape, key order, types and hex fields.

    Every structural, key-order, raw-type, hex, mixed-key, non-finite or
    JSON-serialization defect raises :class:`_Failure` with ``input``.
    Nested evidence records are parsed with the export-record contract
    but are neither replayed nor digest-checked here; those semantic
    checks belong to :func:`verify_state_anchors_audit_report`.
    """
    _stable_canonical_json_bytes(raw_report)
    if (
        not isinstance(raw_report, dict)
        or tuple(raw_report.keys()) != STATE_ANCHORS_AUDIT_REPORT_KEYS
    ):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw_report["v"]) or raw_report["v"] != (
        STATE_ANCHORS_AUDIT_REPORT_VERSION
    ):
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw_report["public_key"]):
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw_report["digest"]):
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex128(raw_report["signature"]):
        raise _Failure(ERR_INPUT)

    raw_sources = raw_report["sources"]
    if not isinstance(raw_sources, list) or not raw_sources:
        raise _Failure(ERR_INPUT)
    sources = []
    seen_paths: set[str] = set()
    for raw_source in raw_sources:
        if (
            not isinstance(raw_source, dict)
            or tuple(raw_source.keys())
            != STATE_ANCHORS_AUDIT_REPORT_SOURCE_KEYS
        ):
            raise _Failure(ERR_INPUT)
        path = raw_source["path"]
        present = raw_source["present"]
        generation = raw_source["generation"]
        digest = raw_source["digest"]
        raw_anchors = raw_source["anchors"]
        if not isinstance(path, str) or not path or path in seen_paths:
            raise _Failure(ERR_INPUT)
        seen_paths.add(path)
        if not isinstance(present, bool):
            raise _Failure(ERR_INPUT)
        if not _is_int(generation):
            raise _Failure(ERR_INPUT)
        if present:
            if generation < 1 or not crypto.is_hex64(digest):
                raise _Failure(ERR_INPUT)
        else:
            if generation != 0 or digest != "":
                raise _Failure(ERR_INPUT)
        if not isinstance(raw_anchors, list):
            raise _Failure(ERR_INPUT)
        anchors = []
        previous_height: int | None = None
        for raw_anchor in raw_anchors:
            if (
                not isinstance(raw_anchor, dict)
                or tuple(raw_anchor.keys()) != STATE_ANCHOR_ANCHOR_KEYS
            ):
                raise _Failure(ERR_INPUT)
            height = raw_anchor["height"]
            if not _is_int(height) or height < 0:
                raise _Failure(ERR_INPUT)
            if previous_height is not None and height <= previous_height:
                raise _Failure(ERR_INPUT)
            previous_height = height
            if not crypto.is_hex64(raw_anchor["block_hash"]):
                raise _Failure(ERR_INPUT)
            if not crypto.is_hex64(raw_anchor["state_root"]):
                raise _Failure(ERR_INPUT)
            anchors.append(
                {key: raw_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS}
            )
        if not present and anchors:
            raise _Failure(ERR_INPUT)
        sources.append(
            {
                "path": path,
                "present": present,
                "generation": generation,
                "digest": digest,
                "anchors": anchors,
            }
        )

    raw_evidence = raw_report["evidence"]
    if not isinstance(raw_evidence, list):
        raise _Failure(ERR_INPUT)
    evidence = []
    seen_pairs: set[tuple[int, str]] = set()
    previous_pair: tuple[int, str] | None = None
    for raw_entry in raw_evidence:
        if (
            not isinstance(raw_entry, dict)
            or tuple(raw_entry.keys())
            != STATE_ANCHORS_AUDIT_REPORT_EVIDENCE_KEYS
        ):
            raise _Failure(ERR_INPUT)
        pair = _state_anchors_audit_pair_entry(
            {"height": raw_entry["height"], "account": raw_entry["account"]}
        )
        if pair in seen_pairs:
            raise _Failure(ERR_INPUT)
        seen_pairs.add(pair)
        if previous_pair is not None and pair < previous_pair:
            raise _Failure(ERR_INPUT)
        previous_pair = pair
        raw_hits = raw_entry["hits"]
        if not isinstance(raw_hits, list) or not raw_hits:
            raise _Failure(ERR_INPUT)
        hits = []
        seen_sources: set[int] = set()
        previous_source: int | None = None
        for raw_hit in raw_hits:
            if (
                not isinstance(raw_hit, dict)
                or tuple(raw_hit.keys()) != STATE_ANCHORS_AUDIT_REPORT_HIT_KEYS
            ):
                raise _Failure(ERR_INPUT)
            source_index = raw_hit["source"]
            if not _is_int(source_index) or not 0 <= source_index < len(
                sources
            ):
                raise _Failure(ERR_INPUT)
            if source_index in seen_sources:
                raise _Failure(ERR_INPUT)
            seen_sources.add(source_index)
            if previous_source is not None and source_index < previous_source:
                raise _Failure(ERR_INPUT)
            previous_source = source_index
            record = _parse_state_anchors_export_record(raw_hit["record"])
            hits.append({"source": source_index, "record": record})
        evidence.append(
            {"height": pair[0], "account": pair[1], "hits": hits}
        )

    groups = {}
    for name in ("verified", "missing", "conflicts"):
        raw_group = raw_report[name]
        if not isinstance(raw_group, list):
            raise _Failure(ERR_INPUT)
        entries = [_state_anchors_audit_pair_entry(item) for item in raw_group]
        if any(
            entries[index] >= entries[index + 1]
            for index in range(len(entries) - 1)
        ):
            raise _Failure(ERR_INPUT)
        groups[name] = entries

    return {
        "v": STATE_ANCHORS_AUDIT_REPORT_VERSION,
        "sources": sources,
        "evidence": evidence,
        "verified": groups["verified"],
        "missing": groups["missing"],
        "conflicts": groups["conflicts"],
        "public_key": raw_report["public_key"],
        "digest": raw_report["digest"],
        "signature": raw_report["signature"],
    }


def verify_state_anchors_audit_report(
    report: object,
    expected_pairs: object,
    public_key: object,
) -> dict:
    """Verify a signed state-anchors audit report offline.

    The report is the sole evidence: no local file is read. ``report`` is
    a document produced by :func:`export_state_anchors_audit_report`,
    ``expected_pairs`` is the pinned non-empty duplicate-free
    ``{"height", "account"}`` list and ``public_key`` is the caller's
    pinned 64-lowercase-hex Ed25519 key. Report or parameter shape, key
    order, type, hex or stable-serialization defects return ``input``.
    A report public key different from the pinned key or a failing
    Ed25519 signature returns ``auth``. A body-digest mismatch, an
    evidence record failing replay or its own digest, a source
    generation/anchor mismatch, a pinned combination appearing outside
    the pinned set, or recomputed verified/missing/conflicts groups
    differing from the report returns ``integrity``.

    Success returns ``{"ok": True, "verified", "missing",
    "conflicts"}`` with the recomputed, stably sorted groups. Nothing is
    raised and arguments are never mutated.
    """
    try:
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(expected_pairs)
        if not isinstance(public_key, str) or not crypto.is_hex64(
            public_key
        ):
            raise _Failure(ERR_INPUT)
        parsed = _parse_state_anchors_audit_report(report)

        if parsed["public_key"] != public_key:
            return {"ok": False, "error": ERR_AUTH}
        expected_digest = _state_anchors_audit_report_digest(
            {
                key: value
                for key, value in report.items()
                if key not in ("digest", "signature")
            }
        )
        if expected_digest != parsed["digest"]:
            return {"ok": False, "error": ERR_INTEGRITY}
        if not crypto.verify_signature(
            public_key,
            _state_anchors_audit_report_message(parsed["digest"]),
            parsed["signature"],
        ):
            return {"ok": False, "error": ERR_AUTH}

        pinned = set(pairs)
        declared = {
            "verified": set(parsed["verified"]),
            "missing": set(parsed["missing"]),
            "conflicts": set(parsed["conflicts"]),
        }
        if (
            declared["verified"] | declared["missing"]
            | declared["conflicts"]
            != pinned
            or len(
                declared["verified"]
                | declared["missing"]
                | declared["conflicts"]
            )
            != len(declared["verified"])
            + len(declared["missing"])
            + len(declared["conflicts"])
        ):
            return {"ok": False, "error": ERR_INTEGRITY}

        pair_evidence: list[dict[tuple, tuple]] = [
            {} for _source in parsed["sources"]
        ]
        source_anchor_maps = [
            {anchor["height"]: anchor for anchor in source["anchors"]}
            for source in parsed["sources"]
        ]
        anchor_votes_by_height: dict[int, list[dict]] = {}
        for source_index, source in enumerate(parsed["sources"]):
            for anchor in source["anchors"]:
                anchor_votes_by_height.setdefault(
                    anchor["height"], []
                ).append(anchor)

        for entry in parsed["evidence"]:
            pair = (entry["height"], entry["account"])
            if pair not in pinned:
                return {"ok": False, "error": ERR_INTEGRITY}
            for hit in entry["hits"]:
                source_index = hit["source"]
                source = parsed["sources"][source_index]
                record = hit["record"]
                if not source["present"]:
                    return {"ok": False, "error": ERR_INTEGRITY}
                if record["generation"] != source["generation"]:
                    return {"ok": False, "error": ERR_INTEGRITY}
                anchor = record["anchor"]
                if (
                    anchor["height"] != pair[0]
                    or record["account"] != pair[1]
                ):
                    return {"ok": False, "error": ERR_INTEGRITY}
                source_anchor = source_anchor_maps[source_index].get(
                    anchor["height"]
                )
                if source_anchor != anchor:
                    return {"ok": False, "error": ERR_INTEGRITY}
                result = verify_state_proofs(
                    record["document"], record["accounts"], record["trust"]
                )
                if not result.get("ok"):
                    return {"ok": False, "error": ERR_INTEGRITY}
                state = record["document"]["state"]
                if anchor != {
                    "height": state["height"],
                    "block_hash": state["block_hash"],
                    "state_root": state["state_root"],
                }:
                    return {"ok": False, "error": ERR_INTEGRITY}
                proof_by_account = {
                    proof["account"]: proof
                    for proof in record["document"]["proofs"]
                }
                if proof_by_account.get(record["account"]) != record["proof"]:
                    return {"ok": False, "error": ERR_INTEGRITY}
                if (
                    _state_anchors_export_record_digest(record)
                    != record["digest"]
                ):
                    return {"ok": False, "error": ERR_INTEGRITY}
                pair_evidence[source_index][pair] = (
                    anchor,
                    record["proof"],
                )

        verified, missing, conflicts = _state_anchors_audit_groups(
            pairs, pair_evidence, anchor_votes_by_height
        )
        if (
            verified
            != [
                {"height": height, "account": account}
                for height, account in parsed["verified"]
            ]
            or missing
            != [
                {"height": height, "account": account}
                for height, account in parsed["missing"]
            ]
            or conflicts
            != [
                {"height": height, "account": account}
                for height, account in parsed["conflicts"]
            ]
        ):
            return {"ok": False, "error": ERR_INTEGRITY}
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    return {
        "ok": True,
        "verified": verified,
        "missing": missing,
        "conflicts": conflicts,
    }

item.stdout:
            overall = AUDIT_STATUS_CORRUPT
        else:
            overall = AUDIT_STATUS_SPLIT
    else:
        # Both stored targets valid and no journal: consistent exactly
        # when the state anchor is bound to the header finalized boundary.
        assert checkpoint is not None and stored is not None
        finalized = checkpoint["finalized"]
        anchor = stored["anchor"]
        bound = (
            anchor["height"] == finalized["height"]
            and anchor["block_hash"] == finalized["block_hash"]
        )
        overall = AUDIT_STATUS_CONSISTENT if bound else AUDIT_STATUS_SPLIT

    return {
        "ok": True,
        "status": overall,
        "header": header_record,
        "state": state_record,
        "transaction": txn_record,
    }


# -- durable batch state-anchor archive --------------------------------------
#
# A local, restartable archive of verified batch signed account-state proofs
# (the ledger-state-proofs-v1 documents verified by verify_state_proofs). One
# version-1 file at a path holds one record per recorded batch: the shared
# anchor (height, block hash, state root), the pinned ascending account set,
# the proof document preserved verbatim and the trust material it verified
# against. Records are independent of arrival order and survive signer
# rotation because every record keeps its own trust document.

STATE_ANCHORS_VERSION = 1
STATE_ANCHORS_KEYS = ("v", "generation", "records", "hash")
STATE_ANCHORS_RECORD_KEYS = ("anchor", "accounts", "document", "trust")
RECORD_STATE_ANCHORS_RESULT_KEYS = (
    "ok",
    "generation",
    "anchor",
    "accounts",
)
READ_STATE_ANCHORS_RESULT_KEYS = ("ok", "generation", "items")
STATE_ANCHORS_ITEM_KEYS = ("anchor", "account", "proof")


def _state_anchors_archive_hash(generation: int, records: list) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    body = {
        "v": STATE_ANCHORS_VERSION,
        "generation": generation,
        "records": records,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _state_anchors_record_sort_key(record: dict) -> tuple:
    """The stable archive order: height first, then the ascending accounts."""
    return (record["anchor"]["height"], tuple(record["accounts"]))


def _state_anchors_input_stage(
    document: object, accounts: object, trust: object
) -> tuple[dict, list[dict]]:
    """Stage-1 (input) structural validation of one record request.

    Mirrors verify_state_proofs' first stage without signer lookup,
    signature or Merkle work: the pinned accounts are a non-empty list of
    distinct 64-lowercase-hex strings, the document carries the exact
    ``state, proofs, auth`` key order with every nested sub-document in
    contract shape, and the trust document carries audit signers. Any
    defect is ``input``.
    """
    if not isinstance(accounts, list) or not accounts:
        raise _Failure(ERR_INPUT)
    if any(not crypto.is_hex64(account) for account in accounts):
        raise _Failure(ERR_INPUT)
    if len(set(accounts)) != len(accounts):
        raise _Failure(ERR_INPUT)
    expected_accounts = sorted(accounts)
    if not isinstance(document, dict) or tuple(document.keys()) != (
        ATTESTED_STATE_PROOFS_KEYS
    ):
        raise _Failure(ERR_INPUT)
    state = _parse_state_root_document(document["state"])
    raw_proofs = document["proofs"]
    if not isinstance(raw_proofs, list) or not raw_proofs:
        raise _Failure(ERR_INPUT)
    proofs = [_parse_state_proof_document(item) for item in raw_proofs]
    raw_auth = document["auth"]
    if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != (
        STATE_PROOF_AUTH_KEYS
    ):
        raise _Failure(ERR_INPUT)
    key_version = raw_auth["key_version"]
    signature = raw_auth["signature"]
    if not _is_int(key_version) or key_version < 1:
        raise _Failure(ERR_INPUT)
    if not isinstance(signature, str) or not crypto.is_hex128(signature):
        raise _Failure(ERR_INPUT)
    _validate_header_trust(trust)
    return state, proofs


def _validate_state_anchors_record(raw_record: object) -> dict:
    """Strictly validate one stored batch state-anchor record.

    Exact key order ``anchor, accounts, document, trust``; the closed
    anchor shape, a non-empty ascending list of distinct 64-hex accounts,
    the exact batch-proof document shape (state/proofs/auth sub-contracts)
    and a trust document carrying audit signers. Beyond shape, the stored
    document is fully re-verified against the record's own stored trust
    with verify_state_proofs and the recorded anchor must be the state
    document's projection — a re-sealed file with a fresh hash over
    tampered content still fails. Every defect is existing-state
    corruption.
    """
    if (
        not isinstance(raw_record, dict)
        or tuple(raw_record.keys()) != STATE_ANCHORS_RECORD_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    raw_anchor = raw_record["anchor"]
    if (
        not isinstance(raw_anchor, dict)
        or tuple(raw_anchor.keys()) != STATE_ANCHOR_ANCHOR_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(raw_anchor["height"]) or raw_anchor["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw_anchor["block_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw_anchor["state_root"]):
        raise _CheckpointError(ERR_STATE)
    anchor = {key: raw_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS}
    raw_accounts = raw_record["accounts"]
    if (
        not isinstance(raw_accounts, list)
        or not raw_accounts
        or any(not crypto.is_hex64(account) for account in raw_accounts)
        or len(set(raw_accounts)) != len(raw_accounts)
        or list(raw_accounts) != sorted(raw_accounts)
    ):
        raise _CheckpointError(ERR_STATE)
    accounts = list(raw_accounts)
    document = raw_record["document"]
    try:
        state = _parse_state_root_document(document["state"])
        raw_proofs = document["proofs"]
        if not isinstance(raw_proofs, list) or not raw_proofs:
            raise _Failure(ERR_INPUT)
        proofs = [_parse_state_proof_document(item) for item in raw_proofs]
        raw_auth = document["auth"]
        if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != (
            STATE_PROOF_AUTH_KEYS
        ):
            raise _Failure(ERR_INPUT)
        key_version = raw_auth["key_version"]
        signature = raw_auth["signature"]
        if not _is_int(key_version) or key_version < 1:
            raise _Failure(ERR_INPUT)
        if not isinstance(signature, str) or not crypto.is_hex128(signature):
            raise _Failure(ERR_INPUT)
        signers = _validate_header_trust(raw_record["trust"])
    except _Failure as failure:
        raise _CheckpointError(ERR_STATE) from failure
    if (
        not isinstance(document, dict)
        or tuple(document.keys()) != ATTESTED_STATE_PROOFS_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    rebuilt_document = {
        "state": state,
        "proofs": proofs,
        "auth": {"key_version": key_version, "signature": signature},
    }
    result = verify_state_proofs(rebuilt_document, accounts, raw_record["trust"])
    if not result.get("ok"):
        raise _CheckpointError(ERR_STATE)
    if anchor != {
        "height": state["height"],
        "block_hash": state["block_hash"],
        "state_root": state["state_root"],
    }:
        raise _CheckpointError(ERR_STATE)
    return {
        "anchor": anchor,
        "accounts": accounts,
        "document": rebuilt_document,
        "trust": raw_record["trust"],
        "_signers": signers,
    }


def _validate_state_anchors_archive(data: object) -> dict:
    """Strictly validate one version-1 batch state-anchor archive.

    Beyond the per-record checks, records must be non-empty, sorted by
    ``(height, accounts)`` with no duplicate ``(height, account set)``
    pair; every record at the same height must name the same block hash
    and state root, and one ``(height, account)`` pair must carry exactly
    one proof content across records (balance, confirmed transactions,
    index and sibling path must agree). The recorded ``hash`` is
    recomputed over the other fields last. Any defect is existing-state
    corruption.
    """
    if not isinstance(data, dict) or tuple(data.keys()) != STATE_ANCHORS_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != STATE_ANCHORS_VERSION:
        raise _CheckpointError(ERR_STATE)
    generation = data["generation"]
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    raw_records = data["records"]
    if not isinstance(raw_records, list) or not raw_records:
        raise _CheckpointError(ERR_STATE)
    records = []
    for raw_record in raw_records:
        record = _validate_state_anchors_record(raw_record)
        record.pop("_signers", None)
        records.append(record)
    previous_key: tuple | None = None
    anchors_by_height: dict[int, dict] = {}
    proofs_by_pair: dict[tuple[int, str], dict] = {}
    for record in records:
        key = _state_anchors_record_sort_key(record)
        if previous_key is not None and key <= previous_key:
            raise _CheckpointError(ERR_STATE)
        previous_key = key
        height = record["anchor"]["height"]
        known_anchor = anchors_by_height.get(height)
        if known_anchor is not None:
            if (
                known_anchor["block_hash"] != record["anchor"]["block_hash"]
                or known_anchor["state_root"] != record["anchor"]["state_root"]
            ):
                raise _CheckpointError(ERR_STATE)
        else:
            anchors_by_height[height] = record["anchor"]
        proof_docs = {
            proof["account"]: proof for proof in record["document"]["proofs"]
        }
        for account in record["accounts"]:
            proof = proof_docs.get(account)
            if proof is None:
                raise _CheckpointError(ERR_STATE)
            pair = (height, account)
            known_proof = proofs_by_pair.get(pair)
            if known_proof is not None and known_proof != proof:
                raise _CheckpointError(ERR_STATE)
            proofs_by_pair.setdefault(pair, proof)
    digest = data["hash"]
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)
    if _state_anchors_archive_hash(generation, records) != digest:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": STATE_ANCHORS_VERSION,
        "generation": generation,
        "records": records,
        "hash": digest,
    }


def _load_state_anchors_archive(path: str) -> dict | None:
    """Strictly load the batch state-anchor archive at ``path``.

    Returns None when the archive is absent. An unreadable file is ``io``;
    bad UTF-8, malformed JSON and every shape/key-order/ordering/digest or
    per-record replay defect is ``state``. The archive is never truncated
    or rebuilt by a read.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_state_anchors_archive(data)


def _atomic_write_state_anchors_archive(path: str, archive: dict) -> None:
    """Write the archive in declared key order and atomically replace ``path``."""
    ordered = {key: archive[key] for key in STATE_ANCHORS_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _stored_state_anchor_proof(record: dict, account: str) -> dict | None:
    """One account's stored proof document from a validated archive record."""
    for proof in record["document"]["proofs"]:
        if proof["account"] == account:
            return proof
    return None


def record_state_anchors(
    path: object,
    document: object,
    accounts: object,
    trust: object,
) -> dict:
    """Verify a batch signed state-proof document and anchor it durably.

    ``document``/``accounts``/``trust`` are exactly the
    :func:`verify_state_proofs` arguments: the decoded batch response
    (key order ``state, proofs, auth``), the caller-pinned non-empty list
    of distinct 64-lowercase-hex accounts and the trust document carrying
    ``audit_signers``. The batch is verified first under the existing
    batch state-proof rules; the shared state root, block height and hash
    plus every account's proof are then stored as one atomic record in
    the version-1 archive at ``path`` (pure library API; the HTTP/CLI
    surface is unchanged).

    The archive carries the exact key order ``v, generation, records,
    hash``; each record keeps ``anchor`` (``height, block_hash,
    state_root``), the ascending ``accounts`` set, the verified
    ``document`` and the ``trust`` material verbatim, sealed by the
    lowercase-hex SHA-256 of the self-excluding canonical JSON. Records
    may arrive for discrete historical heights in any call order; the
    stored order is ``(height, accounts)``.

    The first record starts at generation 1; each genuinely new record
    increments it once. Resubmitting the same anchor with the same
    account set and equivalent proof content (balance, confirmed
    transactions, index and sibling path) is idempotent even if the
    document was re-signed by a later signer: the file bytes and the
    generation hold and the previously saved trust material is kept.
    Conflicts are ``integrity``: the same height naming a different block
    hash or state root, or different proof content for a ``(height,
    account)`` pair already recorded. Signer rotation never invalidates
    historical proofs because each record is re-verified on load against
    its own saved trust.

    Success returns ``{"ok": True, "generation", "anchor", "accounts"}``
    in that key order with ``accounts`` ascending; failure returns only
    ``{"ok": False, "error": category}`` with category one of ``input``
    (parameters, document structure, encoding or non-stable
    serializability), ``auth`` (unknown audit key version or a bad
    Ed25519 signature), ``integrity`` (the batch verifier's account set
    or Merkle failures, or a duplicate-record conflict), ``state`` (a
    corrupt existing archive: parse, field, digest or replay mismatch)
    and ``io`` (a read/write failure). Same-path calls are serialized;
    the write lands via a fsynced temp file and an atomic replace, so a
    crash only ever exposes the old archive or the complete new one.
    Nothing is raised and a failure never changes a file.
    """
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)
    try:
        _state_anchors_input_stage(document, accounts, trust)
        _stable_canonical_json_bytes(document)
        _stable_canonical_json_bytes(trust)
    except _Failure as failure:
        return _failed_advance(failure.category)
    except Exception:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        try:
            stored = _load_state_anchors_archive(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            return _failed_advance(ERR_STATE)

        result = verify_state_proofs(document, accounts, trust)
        if not result.get("ok"):
            return {"ok": False, "error": result["error"]}

        expected_accounts = sorted(accounts)
        new_anchor = {
            "height": result["height"],
            "block_hash": result["block_hash"],
            "state_root": result["state_root"],
        }
        incoming_proofs = {
            proof["account"]: proof for proof in (
                _parse_state_proof_document(item)
                for item in document["proofs"]
            )
        }
        new_record = {
            "anchor": new_anchor,
            "accounts": expected_accounts,
            "document": document,
            "trust": trust,
        }

        if stored is None:
            records: list[dict] = []
            generation = 0
        else:
            records = [
                {
                    "anchor": record["anchor"],
                    "accounts": list(record["accounts"]),
                    "document": record["document"],
                    "trust": record["trust"],
                }
                for record in stored["records"]
            ]
            generation = stored["generation"]

        duplicate_index: int | None = None
        for index, record in enumerate(records):
            if record["anchor"]["height"] != new_anchor["height"]:
                continue
            if (
                record["anchor"]["block_hash"] != new_anchor["block_hash"]
                or record["anchor"]["state_root"] != new_anchor["state_root"]
            ):
                return _failed_advance(ERR_INTEGRITY)
            for account in expected_accounts:
                known_proof = _stored_state_anchor_proof(record, account)
                if known_proof is None:
                    continue
                if known_proof != incoming_proofs[account]:
                    return _failed_advance(ERR_INTEGRITY)
            if list(record["accounts"]) == expected_accounts:
                duplicate_index = index

        if duplicate_index is not None:
            return {
                "ok": True,
                "generation": generation,
                "anchor": {
                    key: records[duplicate_index]["anchor"][key]
                    for key in STATE_ANCHOR_ANCHOR_KEYS
                },
                "accounts": list(expected_accounts),
            }

        records.append(new_record)
        records.sort(key=_state_anchors_record_sort_key)
        next_generation = generation + 1
        archive = {
            "v": STATE_ANCHORS_VERSION,
            "generation": next_generation,
            "records": records,
        }
        archive["hash"] = _state_anchors_archive_hash(
            next_generation, records
        )
        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_state_anchors_archive(path, archive)
        except (TypeError, ValueError):
            _restore_bytes(path, original)
            return _failed_advance(ERR_INPUT)
        except OSError:
            _restore_bytes(path, original)
            return _failed_advance(ERR_IO)

        return {
            "ok": True,
            "generation": next_generation,
            "anchor": {key: new_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS},
            "accounts": list(expected_accounts),
        }


def read_state_anchors(
    path: object,
    height: object = None,
    accounts: object = None,
) -> dict:
    """Read recorded batch state anchors back, restart-safe and read-only.

    ``path`` is the archive maintained by :func:`record_state_anchors`.
    ``height`` optionally pins one non-negative non-boolean block height
    and ``accounts`` an optional non-empty list of distinct
    64-lowercase-hex accounts to select; both default to ``None`` (no
    filter on that dimension). The call never writes, rewrites or cleans
    the archive.

    Success returns ``{"ok": True, "generation", "items"}`` in that key
    order: ``generation`` is the archive generation (0 when the archive
    does not exist) and ``items`` one entry per recorded
    ``(height, account)`` hit, stably sorted by height and then account.
    Each item has key order ``anchor, account, proof`` with ``anchor`` the
    closed ``height, block_hash, state_root`` the proof was recorded under
    and ``proof`` the stored account-state inclusion proof in its fixed
    contract shape. A missing archive, an unknown height or an account
    combination with no hit returns ``{"ok": True, "generation" ...,
    "items": []}`` — only a genuinely corrupt archive is an error.

    Failure returns only ``{"ok": False, "error": category}`` with
    category one of ``input`` (a bad path, height or accounts argument),
    ``state`` (an archive failing its strict parse, field, digest or
    replay checks) and ``io`` (a read failure). Same-path calls share the
    writer lock and nothing is raised; identical file bytes yield
    identical results across restarts.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if height is not None and (not _is_int(height) or height < 0):
        return {"ok": False, "error": ERR_INPUT}
    if accounts is not None:
        if (
            not isinstance(accounts, list)
            or not accounts
            or any(not crypto.is_hex64(account) for account in accounts)
            or len(set(accounts)) != len(accounts)
        ):
            return {"ok": False, "error": ERR_INPUT}
    wanted_accounts = None if accounts is None else set(accounts)

    lock = _checkpoint_lock(path)
    with lock:
        try:
            stored = _load_state_anchors_archive(path)
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        except Exception:
            return {"ok": False, "error": ERR_STATE}
        if stored is None:
            return {"ok": True, "generation": 0, "items": []}

        items = []
        seen_pairs: set[tuple[int, str]] = set()
        for record in stored["records"]:
            record_height = record["anchor"]["height"]
            if height is not None and record_height != height:
                continue
            anchor = {
                key: record["anchor"][key] for key in STATE_ANCHOR_ANCHOR_KEYS
            }
            for account in record["accounts"]:
                if wanted_accounts is not None and account not in wanted_accounts:
                    continue
                pair = (record_height, account)
                if pair in seen_pairs:
                    continue
                proof = _stored_state_anchor_proof(record, account)
                if proof is None:
                    return {"ok": False, "error": ERR_STATE}
                seen_pairs.add(pair)
                items.append({"anchor": anchor, "account": account,
                              "proof": proof})
        items.sort(key=lambda item: (
            item["anchor"]["height"], item["account"]))
        return {
            "ok": True,
            "generation": stored["generation"],
            "items": items,
        }


